36:  throw IosApNetworkUtilityError.invalidDeviceIP
41:  throw IosApNetworkUtilityError.invalidDeviceIP
72:  throw IosApNetworkUtilityError.unavailable
170: continuation.resume(throwing: IosApNetworkUtilityError.userDenied(...))
172: continuation.resume(throwing: IosApNetworkUtilityError.joinFailed(...))
201/204: completion.finish(.failure(IosApNetworkUtilityError.localNetworkDenied(...)))
244: throw IosApNetworkUtilityError.ssidTimedOut(ssid)
313: throw IosApNetworkUtilityError.connectionTimedOut(deviceIP)
346: throw IosApNetworkUtilityError.connectionTimedOut(fallbackDeviceIP)
459: finish(.failure(IosApNetworkUtilityError.localNetworkDenied(...)))
```

调用方（真正触发 AP 握手的地方，`remoteSummary` 里的 `adapter(for: deviceId)` 会走到这里）：

```
packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkIosApNetworkSession.swift
packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkIosNetworkSessions.swift
```
这两个文件调用了 `IosApNetworkUtility.join`/`joinAKW`。

## 第 2 步：`asPigeonError` 实现——是否对网络/AP 错误做了 case 判断

全仓库共 5 处 `asPigeonError` 实现（`identity`/`file_transfer`/`network`/`settings`/`ota_transfer`）。与本问题相关的是 `CoreDeviceFileTransferPlugin.swift`：

```315:329:packages/core/core_device_native_runtime/ios/core_device_native_runtime/Sources/core_device_native_runtime/file_transfer/CoreDeviceFileTransferPlugin.swift
  private func asPigeonError(_ error: Error, fallback: String) -> PigeonError {
    if let error = error as? PigeonError { return error }
    if let error = error as? DeviceTransportNativeOperationError {
      return PigeonError(code: "media_transfer.busy", message: error.code, details: nil)
    }
    if let error = error as? DeviceTransportNativeSessionError {
      let code: String
      switch error {
      case .targetMismatch: code = "media_transfer.target_mismatch"
      case .leaseInvalidated: code = "media_transfer.connection_lost"
      case .notActive: code = "media_transfer.session_not_active"
      }
      return PigeonError(code: code, message: String(describing: error), details: nil)
    }
    return PigeonError(code: fallback, message: error.localizedDescription, details: nil)
  }
```

**结论：只对 `PigeonError`、`DeviceTransportNativeOperationError`、`DeviceTransportNativeSessionError` 三种类型做了 case 级判断，`IosApNetworkUtilityError` 完全没有出现在任何一个 `asPigeonError` 实现里**——它会无条件落入最后一行的 fallback 分支，只保留 `error.localizedDescription`（即 `errorDescription`）作为 message，`code` 用调用方传入的通用 fallback 字符串。

## 第 3 步：`remoteSummary`/`countLogged` 最终传给 Flutter 的 code

`countLogged` 只是记日志后原样 rethrow，不改变错误类型：

```93:102:packages/core/core_device_native_runtime/ios/core_device_native_runtime/Sources/core_device_native_runtime/file_transfer/CoreDeviceFileTransferPlugin.swift
    } catch {
      os_log(
        "remoteSummary count failed kind=%{public}@ deviceId=%{public}@ elapsedMs=%ld errorType=%{public}@ errorMessage=%{public}@",
        log: fileTransferLog, type: .error,
        String(describing: kind), deviceId, Self.elapsedMs(since: start),
        String(describing: type(of: error)), String(describing: error)
      )
      throw error
    }
```

`remoteSummary` 外层 catch 调用 `asPigeonError`：

```65:78:packages/core/core_device_native_runtime/ios/core_device_native_runtime/Sources/core_device_native_runtime/file_transfer/CoreDeviceFileTransferPlugin.swift
      } catch {
        os_log(
          "remoteSummary failed deviceId=%{public}@ totalElapsedMs=%ld errorType=%{public}@ errorMessage=%{public}@",
          log: fileTransferLog, type: .error,
          deviceId, Self.elapsedMs(since: overallStart),
          String(describing: type(of: error)), String(describing: error)
        )
        callback.call(.failure(asPigeonError(error, fallback: "media_transfer.summary_failed")))
      }
```

**答案：code 就是 `"media_transfer.summary_failed"` 这个 fallback**，没有专门的 code；`message` = `IosApNetworkUtilityError.ssidTimedOut(ssid).localizedDescription`，即 `"timed out waiting for Wi-Fi SSID to become <ssid>"`。

## 第 4 步：Dart 侧 `_asAppError`——原生 message 有没有保留

先看 pigeon 生成代码里 Swift `PigeonError → Dart PlatformException` 的桥接，确认 code/message 是原样传递的：

```12:35:packages/core/core_device_native_runtime/lib/src/generated/*.dart
Object? _extractReplyValueOrThrow(
    List<Object?>? replyList,
    String channelName, {
    required bool isNullValid,
}) {
  if (replyList == null) {
    throw PlatformException(
      code: 'channel-error',
      message: 'Unable to establish connection on channel: "$channelName".',
    );
  } else if (replyList.length > 1) {
    throw PlatformException(
      code: replyList[0]! as String,
      message: replyList[1] as String?,
      details: replyList[2],
    );
  } else if (!isNullValid && (replyList.isNotEmpty && replyList[0] == null)) {
    throw PlatformException(
      code: 'null-error',
      message: 'Host platform returned null value for non-null return value.',
    );
  }
  return replyList.firstOrNull;
}
```

再看 `_asAppError` 本体：

```458:478:packages/core/core_device_native_runtime/lib/src/file_transfer/impl/pigeon_device_media_transfer_client.dart
  AppError _asAppError(Object error, String fallbackCode) => switch (error) {
    PlatformException(code: 'channel-error') => const AppError(
      code: 'media_transfer.platform_unavailable',
      message: 'Native media transfer plugin is unavailable',
    ),
    PlatformException(:final code, :final message) => AppError(
      code: code,
      message: message ?? 'Native media transfer failed',
      cause: error,
    ),
    MissingPluginException() => AppError(
      code: 'media_transfer.platform_unavailable',
      message: 'Native media transfer plugin is unavailable',
      cause: error,
    ),
    _ => AppError(
      code: fallbackCode,
      message: 'Native media transfer failed',
      cause: error,
    ),
  };
```

调用点：

```117:130:packages/core/core_device_native_runtime/lib/src/file_transfer/impl/pigeon_device_media_transfer_client.dart
    } on Object catch (error) {
      final mapped = _asAppError(error, 'media_transfer.summary_failed');
      _logger.log(
        AppLogLevel.debug,
        'transfer',
        'remote_summary_failed',
        context: {
          'deviceId': target.deviceId,
          'code': mapped.code,
          'elapsedMs': '${stopwatch.elapsedMilliseconds}',
        },
      );
      return Result.failure(mapped);
    }
```

**结论：`AppError.code = "media_transfer.summary_failed"`（丢失了 `ssidTimedOut` 这个具体 case 信息），但 `AppError.message` 命中的是 `PlatformException(:final code, :final message)` 分支，取的是原生 `message` 字段——也就是 `ssidTimedOut` 的 `errorDescription`（比如 `"timed out waiting for Wi-Fi SSID to become AI_GLASS_47A1"`）。所以原生的可读文本没有丢，被完整塞进了 `AppError.message`，但 `code` 只剩通用兜底值，Dart 侧代码层面无法用 `code` 区分是不是这个具体的 AP 超时。**

## 第 5 步：全仓库引用点 + 有没有专门处理

去重（`.symlinks/plugins` 是 CocoaPods 生成的符号链接，跟 `packages/core/...` 是同一份源码）后，唯一引用这三个字符串的地方：

```
SDK/upgrade-requests.md                                                                          （文档记录，见下）
SDK/IOS/swift-package/sources/WeikeBLECore/Tests/WeikeBLECoreTests/IosApNetworkUtilityTests.swift  （单测只覆盖 invalidDeviceIP，没测 ssidTimedOut）
SDK/IOS/swift-package/sources/WeikeBLECore/Sources/WeikeBLECore/Public/IosApNetworkUtility.swift   （SDK 源码，同一份，双份镜像 cocoapods/swift-package）
packages/core/core_device_native_runtime/ios/core_device_native_runtime/Sources/core_device_native_runtime/file_transfer/CoreDeviceFileTransferPlugin.swift（第 2/3 步已贴）
packages/core/core_device_native_runtime/ios/vendor/WeikeBLECore/Public/IosApNetworkUtility.swift  （第 1 步已贴，符号链接）
packages/core/core_device_native_runtime/lib/src/file_transfer/impl/pigeon_device_media_transfer_client.dart（第 4 步已贴）
```

`SDK/upgrade-requests.md` 里已经有一段与本问题高度相关的既有记录（SDK-010，虽然触发源是 Android `queryRemoteFileCount` 的 `TimeoutCancellationException` 而不是 iOS 的 `ssidTimedOut`，但暴露的是同一条 Dart 兜底路径）：

```253:260:SDK/upgrade-requests.md
- **当前证据**：2026-07-22 真机复测（设备 `C8:01:00:61:47:A1`，deviceCode 8335，
  固件 1.04）：`remoteSummary()` 连续两次在 ~5012ms/5016ms 后以
  `media_transfer.summary_failed`（`_asAppError` 兜底分支，无可诊断分类）失败。
  原生逐段计时（`CoreDeviceFileTransferPlugin.kt`/`.swift` 加的临时日志）定位到
  `adapterFor` 仅 0-8ms，卡点是三个 `count()` 调用中最先执行的 `photo`，异常为
  `kotlinx.coroutines.TimeoutCancellationException: Timed out waiting for 5000 ms`
```

以及所需交付里明确写了"提供超时后的 typed 失败分类（超时/设备拒绝/未实现）而非兜底异常"——说明团队已经意识到这条链路缺少细粒度分类，但目前**尚未解决**。

`ssidTimedOut`/`IosApNetworkUtilityError` 这两个符号在整个 Dart 代码（`lib/`）里**一次都没出现**——没有任何 `switch`/`if (code == ...)` 之类的针对性分支、没有专门的用户提示文案、没有针对该错误的重试策略。Dart 侧对它的处理，就是 `_asAppError` 里那个通用的 `PlatformException(:final code, :final message)` 分支，和其他所有未分类原生异常走的是同一条路。

## 一句话总结

这条错误链路目前是**细粒度错误码在 Dart 侧丢失**：`IosApNetworkUtilityError.ssidTimedOut(ssid)` 这个具体 case 从未被任何 `asPigeonError` 识别，最终只落地为通用的 `AppError(code: "media_transfer.summary_failed")`，仅靠原生 `errorDescription` 拼进 `message` 字段保留可读文本，Dart 侧没有任何代码专门识别或处理这个 AP 超时场景，完全依赖最终的兜底 `message` 展示（且 `SDK/upgrade-requests.md` 里 SDK-010 条目已经记录了这个"无可诊断分类"的已知缺口，尚未解决）。
